oof, werk en dagelijks leven worden zichtbaar in de ervaringen van opeenvolgende generaties. De crisisjaren, de oorlogen in Europa en Azië en de wederopbouw grijpen daarin op elkaar in. Door grote gebeurtenissen naast het leven thuis te leggen, onderzoekt hij hoe een land verandert en hoe families zulke veranderingen meemaken.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/114859/de-eeuw-van-mijn-vader.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/114859/de-eeuw-van-mijn-vader.html","sha256":"ec3f94edcce1f673cc0ab1d4e57eb03a7d97154e44617d235328c51defa73e61","checkedAt":"2026-11-01T20:41:20.867Z","fact":"Paperback ISBN 9789046706466 verschijningsdatum 01/06/2017 NUR 301 Literaire roman, novelle imprint Olympus uitgever Atlas Contact, Uitgeverij taal Nederlands","sourceAuthors":"Geert Mak"},{"url":"https://metadata.isbn.nl/114859/de-eeuw-van-mijn-vader.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"editions","ref":"edition:9789403125008","key":{"id":978200002},"before":{"id":978200002,"title":"Het geluk van Limburg","isbn_10":null,"isbn_13":"9789403125008","work_id":978100018,"cover_id":null,"language":null,"publisher":"Bezige Bij b.v., Uitgeverij De","publish_date":null,"open_library_edition_id":"OL42930397M"},"after":{"id":978200002,"title":"Het geluk van Limburg","isbn_10":null,"isbn_13":"9789403125008","work_id":978100018,"cover_id":null,"language":"nld","publisher":"Bezige Bij b.v., Uitgeverij De","publish_date":null,"open_library_edition_id":"OL42930397M"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789403125008","key":{"edition_id":978200002},"before":n